static void printOperand(MCInst *MI, unsigned OpNo, SStream *O)
{
        MCOperand *Op  = MCInst_getOperand(MI, OpNo);
        if (MCOperand_isReg(Op)) {
                unsigned int reg = MCOperand_getReg(Op);
                printRegName(O, reg);
                if (MI->csh->detail) {
                        if (MI->csh->doing_mem) {
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(reg);
                        } else {
                                uint8_t access[6];

                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_REG;
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].reg = X86_register_map(reg);
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->csh->regsize_map[X86_register_map(reg)];

                                get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];

                                MI->flat_insn->detail->x86.op_count++;
                        }
                }
        } else if (MCOperand_isImm(Op)) {
                // Print X86 immediates as signed values.
                uint8_t encsize;
                int64_t imm = MCOperand_getImm(Op);
                uint8_t opsize = X86_immediate_size(MCInst_getOpcode(MI), &encsize);

                if (opsize == 1)    // print 1 byte immediate in positive form
                        imm = imm & 0xff;

                switch(MI->flat_insn->id) {
                        default:
                                if (imm >= 0) {
                                        if (imm > HEX_THRESHOLD)
                                                SStream_concat(O, "$0x%"PRIx64, imm);
                                        else
                                                SStream_concat(O, "$%"PRIu64, imm);
                                } else {
                                        if (MI->csh->imm_unsigned) {
                                                if (opsize) {
                                                        switch(opsize) {
                                                                default:
                                                                        break;
                                                                case 1:
                                                                        imm &= 0xff;
                                                                        break;
                                                                case 2:
                                                                        imm &= 0xffff;
                                                                        break;
                                                                case 4:
                                                                        imm &= 0xffffffff;
                                                                        break;
                                                        }
                                                }

                                                SStream_concat(O, "$0x%"PRIx64, imm);
                                        } else {
                                                if (imm == 0x8000000000000000LL)  // imm == -imm
                                                        SStream_concat0(O, "$0x8000000000000000");
                                                else if (imm < -HEX_THRESHOLD)
                                                        SStream_concat(O, "$-0x%"PRIx64, -imm);
                                                else
                                                        SStream_concat(O, "$-%"PRIu64, -imm);
                                        }
                                }
                                break;

                        case X86_INS_MOVABS:
                        case X86_INS_MOV:
                                // do not print number in negative form
                                SStream_concat(O, "$0x%"PRIx64, imm);
                                break;

                        case X86_INS_IN:
                        case X86_INS_OUT:
                        case X86_INS_INT:
                                // do not print number in negative form
                                imm = imm & 0xff;
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        SStream_concat(O, "$%u", imm);
                                else {
                                        SStream_concat(O, "$0x%x", imm);
                                }
                                break;

                        case X86_INS_LCALL:
                        case X86_INS_LJMP:
                        case X86_INS_JMP:
                                // always print address in positive form
                                if (OpNo == 1) {        // selector is ptr16
                                        imm = imm & 0xffff;
                                        opsize = 2;
                                } else
                                        opsize = 4;
                                SStream_concat(O, "$0x%"PRIx64, imm);
                                break;

                        case X86_INS_AND:
                        case X86_INS_OR:
                        case X86_INS_XOR:
                                // do not print number in negative form
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        SStream_concat(O, "$%u", imm);
                                else {
                                        imm = arch_masks[opsize? opsize : MI->imm_size] & imm;
                                        SStream_concat(O, "$0x%"PRIx64, imm);
                                }
                                break;

                        case X86_INS_RET:
                        case X86_INS_RETF:
                                // RET imm16
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        SStream_concat(O, "$%u", imm);
                                else {
                                        imm = 0xffff & imm;
                                        SStream_concat(O, "$0x%x", imm);
                                }
                                break;
                }

                if (MI->csh->detail) {
                        if (MI->csh->doing_mem) {
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = imm;
                        } else {
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
                                MI->has_imm = true;
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;

                                if (opsize > 0) {
                                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
                                        MI->flat_insn->detail->x86.encoding.imm_size = encsize;
                                } else if (MI->op1_size > 0)
                                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->op1_size;
                                else
                                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;

                                MI->flat_insn->detail->x86.op_count++;
                        }
                }
        }
}

static void printMemReference(MCInst *MI, unsigned Op, SStream *O)
{
        MCOperand *BaseReg  = MCInst_getOperand(MI, Op + X86_AddrBaseReg);
        MCOperand *IndexReg  = MCInst_getOperand(MI, Op + X86_AddrIndexReg);
        MCOperand *DispSpec = MCInst_getOperand(MI, Op + X86_AddrDisp);
        MCOperand *SegReg = MCInst_getOperand(MI, Op + X86_AddrSegmentReg);
        uint64_t ScaleVal;
        int segreg;
        int64_t DispVal = 1;

        if (MI->csh->detail) {
                uint8_t access[6];

                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(MCOperand_getReg(BaseReg));
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_register_map(MCOperand_getReg(IndexReg));
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = 1;
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;

                get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
        }

        // If this has a segment register, print it.
        segreg = MCOperand_getReg(SegReg);
        if (segreg) {
                _printOperand(MI, Op + X86_AddrSegmentReg, O);
                SStream_concat0(O, ":");

                if (MI->csh->detail) {
                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_register_map(segreg);
                }
        }

        if (MCOperand_isImm(DispSpec)) {
                DispVal = MCOperand_getImm(DispSpec);
                if (MI->csh->detail)
                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = DispVal;
                if (DispVal) {
                        if (MCOperand_getReg(IndexReg) || MCOperand_getReg(BaseReg)) {
                                printInt64(O, DispVal);
                        } else {
                                // only immediate as address of memory
                                if (DispVal < 0) {
                                        SStream_concat(O, "0x%"PRIx64, arch_masks[MI->csh->mode] & DispVal);
                                } else {
                                        if (DispVal > HEX_THRESHOLD)
                                                SStream_concat(O, "0x%"PRIx64, DispVal);
                                        else
                                                SStream_concat(O, "%"PRIu64, DispVal);
                                }
                        }
                }
        }

        if (MCOperand_getReg(IndexReg) || MCOperand_getReg(BaseReg)) {
                SStream_concat0(O, "(");

                if (MCOperand_getReg(BaseReg))
                        _printOperand(MI, Op + X86_AddrBaseReg, O);
